    self,
    workflow: Workflow,
    state: dict[str, Any],
    map_id: str,
    loop_id: str | None,
    iteration: int | None,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    """Resolve a referenced dynamic node to its container, state, and context.

    Without a loop context the reference names a map declared outside a
    loop body; with one it names that map's expansion in the given
    iteration (only the current iteration of a running loop ever holds
    instances an instance operation may touch). A reference to anything
    else is the usual missing resource.
    """
    if not any(node.id == map_id and node.kind == "map" for node in workflow.nodes):
        raise NotFoundError(f"map node {map_id} was not found")
    if loop_id is None:
        maps = state.get("maps") or {}
        if map_id not in maps:
            raise NotFoundError(f"map node {map_id} was not found")
        return state, maps[map_id], {}
    loop_state = state.get("loops", {}).get(loop_id)
    if loop_state is None or not isinstance(iteration, int) or not 1 <= iteration <= len(loop_state["iterations"]):
        raise NotFoundError(f"map node {map_id} was not found")
    if iteration != loop_state["current_iteration"] or loop_state["status"] != "running":
        raise NotFoundError(f"map node {map_id} was not found")
    iteration_record = loop_state["iterations"][iteration - 1]
    map_state = (iteration_record.get("maps") or {}).get(map_id)
    if map_state is None:
        raise NotFoundError(f"map node {map_id} was not found")
    context = {"loop_id": loop_id, "iteration": iteration}
    return iteration_record, map_state, context

