def _locate_map_state(
    self, workflow: Workflow, state: dict[str, Any], map_id: str
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    """Resolve a referenced dynamic node to its container, state, and context.

    A map declared outside a loop body lives in the execution-level map
    records; a map nested in a loop body belongs to its owner loop, and
    only that loop's current running iteration can hold actionable
    instances, so the context is derived rather than supplied. A map that
    has no expansion to reference is a missing resource.
    """
    node = next((item for item in workflow.nodes if item.id == map_id and item.kind == "map"), None)
    if node is None:
        raise NotFoundError(f"map node {map_id} was not found")
    owner_loop = next(
        (owner for owner, body in workflow.loop_bodies().items() if map_id in body), None
    )
    if owner_loop is None:
        maps = state.get("maps") or {}
        if map_id not in maps:
            raise NotFoundError(f"map node {map_id} was not found")
        return state, maps[map_id], {}
    loop_state = state.get("loops", {}).get(owner_loop)
    if loop_state is None or loop_state["status"] != "running":
        raise NotFoundError(f"map node {map_id} was not found")
    iteration = loop_state["current_iteration"]
    iteration_record = loop_state["iterations"][iteration - 1]
    map_state = (iteration_record.get("maps") or {}).get(map_id)
    if map_state is None:
        raise NotFoundError(f"map node {map_id} was not found")
    return iteration_record, map_state, {"loop_id": owner_loop, "iteration": iteration}

def _instance_operation_scope(
    self, execution_id: str, map_id: str, tenant: str
) -> str | None:
    """Read-only identity of the map's current expansion, for idempotency scoping.

    The same element index recurs in every iteration of a nested map, so
    the operation identity carries the owning iteration: reusing one key
    against a different iteration is key reuse across operations, exactly
    like migrations to different versions. Returns None only when the
    referenced dynamic node does not exist at all.
    """
    row = self.store.connection.execute(
        "SELECT 1 FROM executions WHERE tenant = ? AND id = ?",
        (tenant, execution_id),
    ).fetchone()
    if row is None:
        return None
    workflow = self._bound_workflow(execution_id, tenant)
    if not any(node.id == map_id and node.kind == "map" for node in workflow.nodes):
        return None
    state_row = self.store.connection.execute(
        "SELECT state FROM executions WHERE tenant = ? AND id = ?",
        (tenant, execution_id),
    ).fetchone()
    state = self.store.decode(state_row["state"])
    owner_loop = next(
        (owner for owner, body in workflow.loop_bodies().items() if map_id in body), None
    )
    if owner_loop is None:
        return f"{execution_id}:{map_id}"
    loop_state = state.get("loops", {}).get(owner_loop)
    if loop_state is None or loop_state["status"] != "running":
        return f"{execution_id}:{map_id}"
    return f"{execution_id}:{map_id}:{owner_loop}:{loop_state['current_iteration']}"

