        map_state = (iteration_record.get("maps") or {}).get(map_id)
        if map_state is None:
            raise NotFoundError(f"map node {map_id} was not found")
        return iteration_record, map_state, {"loop_id": owner_loop, "iteration": iteration}
    # A finished (or never-started) loop holds no actionable instance;
    # locate the element in a recorded iteration so an existing instance
    # conflicts as already advanced instead of looking missing.
    if loop_state is not None:
