def _with_map_instance_input(instance: dict[str, Any], replacement: dict[str, Any]) -> dict[str, Any]:
    """Return an instance record carrying rewritten input in a stable key order.

    The ``input`` field exists only on an instance once it has been rewritten;
    rebuilding the record instead of appending the key keeps its order
    identical between the operation response, replay, and later reads.
    """
    return {
        "index": instance["index"],
        "input": replacement,
        "status": instance["status"],
        "output": instance["output"],
        "failure_reason": instance["failure_reason"],
    }

